// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Türk ve dünya tiyatro edebiyatı: trajedi, komedi, dram ve çağdaş oyun yazarları (Sofokles, Shakespeare, Molière, İbsen, Çehov, Brecht, Haldun Taner) (kolay).
const ozLiterature16Kolay = <(String, String, List<String>, String)>[
  ('Atina\'da bağ bozumu ve şarap tanrısı onuruna düzenlenen, trajedi ile komedi yarışmalarının kurumsal zemini sayılan dinsel törenler hangisidir?', 'Büyük Dionysia Şenlikleri', ['Eleusis Gizem Ayinleri', 'Panathenaia Geçit Törenleri', 'Delphoi Pythia Oyunları'], 'Antik Yunan\'da tiyatro sanatı, şarap ve bereket tanrısı Dionysos adına yapılan Büyük Dionysia şenliklerindeki koro ezgilerinden doğmuştur.'),
  ('Dionysos korosunun söylediği coşkulu ilahilerden sıyrılarak koroyla karşılıklı konuşan ilk oyuncuyu sahneye çıkaran ve tarihte ilk aktör kabul edilen sanatçı kimdir?', 'İkarialı Thespis', ['Giritli Epimenides', 'Lesboslu Arion', 'Korinthoslu Periander'], 'MÖ 6. yüzyılda Thespis, dithyrambos korosunun karşısına \'hypokrites\' (yanıt veren) sıfatıyla tek bir oyuncu çıkararak dramatik diyaloğu başlatmıştır.'),
  ('Dithyrambos adı verilen koro ezgilerinde koroyu yöneten, yeri geldiğinde oyuncularla söz alışverişine giren koro başı görevlisine Antik Yunan tiyatrosunda ne ad verilirdi?', 'Korife (Koryphaios)', ['Arkhon Eponymos', 'Khoregos (Sponsor)', 'Rhapsodos (Anlatıcı)'], 'Koro üyelerinin başında duran, ezgi ve dans uyumunu sağlayan ve koroyu temsilen konuşan lidere korife (koryphaios) denirdi.'),
  ('Aristoteles\'in Poetika adlı yapıtında trajedinin seyircide acıma ve korku duyguları uyandırarak ruhu tutkularından arındırması işlevi hangi kavramla karşılanır?', 'Katarsis', ['Mimesis', 'Anagnorisis', 'Peripeteia'], 'Katarsis (arınma), seyircinin trajik kahramanın yıkımına tanıklık ederken korku ve acıma yoluyla duygusal sağaltım yaşamasıdır.'),
  ('Trajik kahramanın tanrısal yasaları veya kozmik ölçüyü hiçe sayarak aşırı kibre ve haddi aşma cüretine kapılmasını anlatan Antik Yunan terimi hangisidir?', 'Hubris', ['Sophrosyne', 'Ataraksia', 'Eudaimonia'], 'Hubris, insanın kendi sınırlarını unutup tanrılara kafa tutacak ölçüde kibre kapılmasıdır ve trajedilerde genellikle felaketi davet eder.'),
  ('İçinden çıkılmaz biçimde düğümlenen olay örgüsünü çözmek üzere sahneye vinç yardımıyla indirilen doğaüstü gücü anlatan Latince deyim hangisidir?', 'Deus ex machina', ['In medias res', 'Dramatis personae', 'Persona non grata'], 'Yunanca \'theos apo mekhanes\' ifadesinin karşılığı olan deus ex machina (makineden çıkan tanrı), özellikle Euripides oyunlarında düğümü çözen yapay müdahaledir.'),
  ('Açık hava tiyatrolarında koronun dans edip ezgiler söylediği, ortasında Dionysos sunağı (thymele) bulunan dairesel alana hangi ad verilir?', 'Orkestra', ['Theatron', 'Logeion', 'Kerkides'], 'Yunanca \'dans yeri\' anlamına gelen orkestra, Antik Yunan tiyatro mimarisinin çekirdeğini oluşturan dairesel performans alanıdır.'),
  ('Sahneye ikinci oyuncuyu (deuteragonistes) ekleyerek diyalog olanaklarını genişleten ve koro ağırlığını azaltıp dramatik çatışmayı kuran \'trajedinin babası\' kimdir?', 'Aiskhylos', ['Phrynichos', 'Kratinos', 'Eupolis'], 'Aristoteles\'in belirttiği üzere Aiskhylos oyuncu sayısını birden ikiye çıkarmış, böylece korodan bağımsız gerçek dramatik çatışmanın temelini atmıştır.'),
  ('İnsanlığa ateşi ve uygarlık sanatlarını armağan ettiği için Zeus\'un emriyle Kafkas Dağları\'nda ıssız bir kayaya çivilenen Titan\'ın başeğmez direnişini hangi eser anlatır?', 'Zincire Vurulmuş Prometheus', ['Tebai\'ye Karşı Yediler', 'Oidipus Kolonos\'ta', 'Herakles Çıldırıyor'], 'Aiskhylos\'a atfedilen Zincire Vurulmuş Prometheus, zorba otoriteye karşı bilginin, özgür iradenin ve insanlık sevgisinin trajik başkaldırısını simgeler.'),
  ('Sahneye üçüncü oyuncuyu (tritagonistes) çıkaran, sahne resimlemesini (skenographia) geliştiren ve bağlı üçleme zorunluluğunu kırarak tekil başyapıtlar yazan şair kimdir?', 'Sofokles', ['Theognis', 'Bakkhylides', 'Kallimakhos'], 'Sofokles üçüncü aktörü ekleyerek çok yönlü karakter çatışmalarını mümkün kılmış, koro sayısını 12\'den 15\'e yükseltmiş ve bağımsız trajediler kaleme almıştır.'),
  ('Tebai kentini kasıp kavuran veba salgınını durdurmak amacıyla Kral Laios\'un katilini ararken, adım adım aradığı suçlunun bizzat kendisi olduğunu öğrenen kahramanın trajedisi hangisidir?', 'Kral Oidipus', ['Philoktetes', 'İphigenia Tauris\'te', 'Bakkhalar'], 'Sofokles\'in Kral Oidipus\'u, Aristoteles tarafından dramatik kurgu, trajik ironi, peripeteia ve anagnorisisin en kusursuz örneği sayılmıştır.'),
  ('Kral Kreon\'un devlet fermanına rağmen vatan haini ilan edilen kardeşi Polyneikes\'in ölüsünü açıkta bırakmayıp toprağa serpen genç kızın vicdan ve yasa çatışmasını hangi oyun işler?', 'Antigone', ['Elektra', 'Alkestis', 'Andromakhe'], 'Sofokles\'in Antigone adlı trajedisi, hükümdarın geçici pozitif hukuku ile tanrısal-vicdani yazısız yasalar arasındaki uzlaşmaz çatışmayı anıtlaştırır.'),
  ('Aristoteles\'in \'Sofokles insanları olmaları gerektiği gibi, o ise oldukları gibi betimler\' sözüyle geleneksel mitleri psikolojik gerçekçilik ve kuşkuculukla sarstığını belirttiği üçüncü büyük trajedi şairi kimdir?', 'Euripides', ['Simonides', 'Pindaros', 'Mimnermos'], 'Euripides, tanrıları ve efsanevi kahramanları insani zaafları, tutkuları ve toplumsal dışlanmışlıklarıyla ele alarak modern psikolojik dramın öncüsü olmuştur.'),
  ('Uğruna vatanını ve ailesini feda ettiği İason\'un Korinthos Kralı\'nın kızıyla evlenmeye kalkması üzerine, kocasından öç almak için kendi iki çocuğunu öldüren büyücü kadının trajedisi hangisidir?', 'Medea', ['Phaidra', 'Kassandra', 'Deianeira'], 'Euripides\'in MÖ 431 tarihli başyapıtı Medea, aldatılan ve yabancı (barbar) sayılarak hor görülen bir kadının korkunç intikam tutkusunu derinlemesine çözümler.'),
  ('Atina\'da siyasal taşlama özgürlüğünün (parrhesia) doruğa çıktığı MÖ 5. yüzyıl Eski Komedya (Arkaia) türünün günümüze tam metinleri ulaşan tek büyük temsilcisi kimdir?', 'Aristofanes', ['Menandros', 'Philemon', 'Epikharmos'], 'Aristofanes, Peloponnesos Savaşı yıllarında devlet adamlarını, demagogları, filozofları ve edebiyatçıları keskin ve fantastik bir hicivle sahneye taşımıştır.'),
  ('Peloponnesos Savaşı\'nı sona erdirmek için Atinalı ve Spartalı kadınların birleşerek Akropolis hazinesini ele geçirmesini ve erkekler barış anlaşması imzalayana dek aşk grevi yapmasını işleyen oyun hangisidir?', 'Lysistrata', ['Thesmophoriazusai', 'Akharnialılar', 'Dyskolos'], 'Aristofanes\'in MÖ 411\'de sahnelenen Lysistrata (\'Orduları Dağıtan Kadın\') komedyası, dünya tiyatro tarihinin en ünlü savaş karşıtı yapıtlarından biridir.'),
  ('Halk dilinin canlılığını, müzikli bölümleri (cantica) ve kurnaz köle (servus callidus) tipini ustalıkla kullanarak Roma komedyasını zirveye taşıyan, Çömlek ve İkizler oyunlarının yazarı kimdir?', 'Titus Maccius Plautus', ['Publius Terentius Afer', 'Lucius Accius', 'Gaius Lucilius'], 'Plautus, Yunan Yeni Komedyası metinlerini Roma halkının beğeneceği enerjik fars, söz oyunları ve şarkılı sahnelerle yoğurarak ölümsüzleştirmiştir.'),
  ('Antik Yunan sahnesinde binlerce kişilik açık hava tiyatrosunda yüz ifadelerinin uzaktan seçilmesini sağlayan, cinsiyet ve yaş bildiren keten veya ahşap aksesuar hangisidir?', 'Prosopon (Maske)', ['Khlamys (Pelerin)', 'Thyrsos (Asa)', 'Onkos (Peruka tepeliği)'], 'Yunancada \'yüz\' anlamına da gelen prosopon (maske), üç oyuncunun birden fazla rolü ve kadın karakterleri canlandırmasına olanak tanımıştır.'),
  ('Yunan trajedisinde başrolü üstlenen, oyunun merkezindeki çatışmayı sırtlayan birinci aktöre hangi terimle seslenilirdi?', 'Protagonistes', ['Antagonistes', 'Khoreutes', 'Didaskalos'], 'Protagonistes (\'ilk yarışmacı/oyuncu\'), trajedide ana rolü oynayan başaktördür; karşısındaki ikinci ve üçüncü oyunculara deuteragonistes ve tritagonistes denirdi.'),
  ('Sofokles ve Euripides\'in aynı mitolojik kişiyi anlattığı Elektra trajedilerinin her ikisinde de kız kardeşin Yunan ordusu komutanı olan babasının öcünü almak üzere yolunu gözlediği sürgündeki erkek kardeşi kimdir?', 'Orestes', ['Menelaos', 'Diomedes', 'Hippolytos'], 'Agamemnon\'un kızı Elektra, annesi Klytaimnestra ve onun sevgilisi Aigisthos\'tan babasının kanını sormak için kardeşi Orestes\'in dönüşünü bekler.'),
  ('Kral Oidipus ve Antigone trajedilerinin her ikisinde de sahneye çıkarak hükümdarlara hakikati ve tanrıların öfkesini bildiren, gözleri görmediği halde gerçeği herkesten berrak sezen Tebaili bilici kimdir?', 'Teiresias', ['Kalkhas', 'Amphiaraos', 'Laokoon'], 'Kör kahin Teiresias, hem Oidipus\'a aradığı katilin kendisi olduğunu hem de Kreon\'a Antigone\'yi diri diri gömmesinin felaket getireceğini haber verir.'),
  ('Klasik Yunan trajedisi ile Eski Komedya konuları ve kişileri bakımından karşılaştırıldığında hangi yargı doğrudur?', 'Trajedi konularını mitolojiden ve soylulardan seçerken Eski Komedya güncel siyaseti ve sıradan insanları işler', ['Trajedi her zaman düzyazı ile kaleme alınırken Eski Komedya yalnızca heksametron ölçüsü kullanır', 'Trajedide kadın rollerini kadın aktrisler oynarken Eski Komedya\'da yalnız erkekler sahneye çıkar', 'Trajedide koro yirmi dört kişiden oluşurken Eski Komedya\'da koro tümüyle kaldırılmıştır'], 'Trajedi kahramanlarını mitoslardan ve kral soyundan (Persler istisnası dışında) seçerken; Eski Komedya kurgusal halk tiplerini ve yaşayan Atinalı siyasetçileri sahneye çıkarır (koro komedyada 24, klasik trajedide 12-15 kişidir).'),
  ('Antik Yunan açık hava tiyatrosunda yarım daire veya at nalı biçimindeki basamaklı yamaca yerleşerek oyunu izleyen seyircilerin oturduğu bölüme ne ad verilirdi?', 'Theatron', ['Proskenion', 'Paraskenia', 'Hyposkenion'], 'Yunanca \'görme/izleme yeri\' anlamına gelen theatron (mimari çanak olarak koilon), yamaca oyulmuş taş veya ahşap seyirci basamaklarını ifade eder ve \'tiyatro\' sözcüğünün köküdür.'),
  ('16. yüzyıl İtalya\'sında yazılı tam bir metne bağlı kalmaksızın yalnızca \'canovaccio\' denilen olay taslağı üzerinden maskeli sabit tiplerin doğaçlama yeteneğiyle oynadığı profesyonel halk tiyatrosu hangisidir?', 'Commedia dell\'arte', ['Commedia erudita', 'Opera seria', 'Teatro olimpico'], 'Commedia dell\'arte, gezici profesyonel kumpanyaların doğaçlama replikler ve akrobatik şakalarla (lazzi) oynadığı, Avrupa komedyasını biçimlendiren İtalyan geleneğidir.'),
  ('Commedia dell\'arte geleneğinde baklava dilimli rengârenk yamalı giysisi, siyah yarım maskesi ve çevik akrobatik hareketleriyle tanınan kurnaz ama saf uşak tipi hangisidir?', 'Arlecchino (Harlequin)', ['Pantalone (Venedikli tüccar)', 'Il Dottore (Bolognalı bilgin)', 'Il Capitano (İspanyol asker)'], 'Bergamo kökenli uşak tipi zanni grubunun en ünlüsü olan Arlecchino, renkli yamalı kostümü ve sopasıyla (batocchio) dünya tiyatrosunun simgelerindendir.'),
  ('Londra\'da Thames Nehri\'nin güney kıyısında 1599 yılında Shakespeare\'in de ortağı olduğu Lord Chamberlain\'s Men kumpanyası tarafından inşa edilen üstü kısmen açık, çokgen planlı ünlü tiyatro yapısı hangisidir?', 'Globe Tiyatrosu', ['Drury Lane Kraliyet Tiyatrosu', 'Covent Garden Sahnesi', 'Blackfriars Manastır Salonu'], 'Shakespeare\'in en büyük trajedilerinin sahnelendiği Globe Tiyatrosu, sahne önüne dikilip bir peni ödeyen halktan seyircilerle (groundlings) localardaki soyluları aynı çatıda buluşturmuştur.'),
  ('Danimarka kalesi Elsinore\'un burçlarında babasının hayaletiyle karşılaştıktan sonra amcası Claudius\'un suçunu kanıtlamak için gezici oyunculara \'Gonzago\'nun Öldürülmesi\' (Fare Kapanı) adlı oyunu oynatan trajik kahraman kimdir?', 'Prens Hamlet', ['Venedik Mağribisi Othello', 'İskoçya Beyi Macbeth', 'Veronalı Romeo Montague'], 'Shakespeare\'in Hamlet trajedisinde kahraman, \'tiyatro içinde tiyatro\' tekniğini kullanarak Kral Claudius\'un yüzündeki suçluluk tepkisini ölçer.'),
  ('Üç cadının kehaneti ve hırslı eşinin kışkırtmasıyla misafiri Kral Duncan\'ı uykusunda hançerleyen, ardından ellerindeki hayali kan lekelerini bir türlü çıkaramayan eşinin uyurgezerlik içinde yıkıldığı Shakespeare trajedisi hangisidir?', 'Macbeth', ['Coriolanus', 'Titus Andronicus', 'Cymbeline'], 'İskoçya\'da geçen Macbeth, iktidar hırsının vicdanı nasıl çürüttüğünü ve Birnam Ormanı\'nın yürüyüşü kehanetiyle gelen kaçınılmaz sonu en yoğun biçimde işler.'),
  ('Sancaktarlığa terfi ettirilmemesinin kiniyle komutanını \'yeşil gözlü canavar\' olarak nitelediği kıskançlık zehriyle adım adım zehirleyen ve düşürülmüş çilekli bir mendili ihanet kanıtı gibi kullanan kötücül karakter kimdir?', 'İago', ['Cassio', 'Tybalt', 'Mercutio'], 'Shakespeare\'in Othello trajedisinde İago, komutanı Othello\'yu masum eşi Desdemona\'nın Cassio ile ilişkisi olduğuna inandırarak korkunç cinayeti tezgâhlar.'),
  ('Ülkesini üç kızı arasında paylaştırırken Goneril ve Regan\'ın sahte övgülerine kanıp kendisini dürüstçe seven küçük kızı Cordelia\'yı mirastan kovan yaşlı hükümdarın fırtınalı bozkırda deliliğe sürüklenişini hangi oyun anlatır?', 'Kral Lear', ['III. Richard', 'Kral John', 'Atinalı Timon'], 'Shakespeare\'in Kral Lear trajedisi; evlat nankörlüğünü, iktidar körlüğünü ve her şeyini yitirdikten sonra Soytarı\'nın eşliğinde kazanılan acı bilgeliği destanlaştırır.'),
  ('Verona kentinin iki düşman ailesi Montague ve Capuletlerin çocukları arasındaki kavuşamayan aşkı, Rahip Laurence\'ın verdiği kırk iki saatlik ölüm uykusu iksirinin trajik zamanlama hatasıyla sonlandıran eser hangisidir?', 'Romeo ve Juliet', ['Antonius ve Kleopatra', 'Troilus ve Cressida', 'İki Soylu Akraba'], 'Romeo, habercinin veba karantinası yüzünden kendisine ulaşamaması sonucu Juliet\'i gerçekten öldü sanarak mezarda zehir içer; uyanan Juliet de hançerle canına kıyar.'),
  ('Asıl adı Jean-Baptiste Poquelin olan, hem yazar hem yönetmen hem de başoyuncu sıfatıyla Fransız karakter ve töre komedyasını evrensel zirveye çıkaran 17. yüzyıl sanatçısı kimdir?', 'Molière', ['Marivaux', 'Regnard', 'Scarron'], 'Molière, insan kusurlarını (cimrilik, ikiyüzlü dindarlık, züppelik, hastalık kuruntusu) gülünçleştirerek eğlendirirken düşündüren klasik karakter komedyasını kurmuştur.'),
  ('Bahçesine gömdüğü on bin altınlık çekmecesi çalınınca seyircilere bile dönüp hırsızı arayan, oğlu Cléante\'ın sevdiği genç kız Mariane ile \'çeyizsiz\' evlenmeye kalkan Harpagon tipini ölümsüzleştiren Molière eseri hangisidir?', 'Cimri (L\'Avare)', ['Adamcıl (Le Misanthrope)', 'Şaşkın (L\'Étourdi)', 'Amphitryon'], 'Molière\'in 1668\'de düzyazıyla kaleme aldığı Cimri, para tutkusunun aile bağlarını ve babalık sevgisini nasıl kuruttuğunu Harpagon karakteriyle sergiler.'),
  ('Saf ve dindar aile babası Orgon\'un evine postu serip sahte sofuluk gösterileriyle hem ailenin servetini tapulayan hem de evin hanımı Elmire\'i baştan çıkarmaya yeltenen riyakâr tip hangi Molière komedyasına adını vermiştir?', 'Tartuffe', ['George Dandin', 'Scapin\'in Dolapları', 'Kocalar Mektebi'], 'Din istismarcılığını teşhir ettiği için bağnaz çevrelerin tepkisiyle beş yıl boyunca (1664-1669) yasaklanan ve yeniden yazılan Tartuffe, dünya edebiyatında ikiyüzlülüğün eş anlamlısı olmuştur.'),
  ('Varlıklı kumaş tüccarı soyundan gelen saf Mösyö Jourdain\'in asilzade görünmek hevesiyle eskrim, dans ve felsefe hocaları tutmasını, kırk yıldır farkında olmadan \'düzyazı\' konuştuğunu öğrenince çocuk gibi sevinmesini anlatan oyun hangisidir?', 'Kibarlık Budalası', ['Gülünç Kibarlar', 'Bilgiç Kadınlar', 'Zoraki Evlenme'], '1670\'te besteci Lully ile \'komedi-bale\' olarak hazırlanan Kibarlık Budalası (Le Bourgeois gentilhomme), Osmanlı elçiliği krizi üzerine eklenen sahte \'Mamamouchi\' töreniyle de ünlüdür.'),
  ('Sapasağlam olduğu halde şarlatan hekimlerin ve eczacıların elinde sürekli lavman ve ilaçlarla yaşayan, kızını sırf bedava muayene olabilmek için aptal bir doktor adayıyla evlendirmeye kalkan Argan\'ın komedyası hangisidir?', 'Hastalık Hastası', ['Zoraki Hekim', 'Aşk Hekimi', 'Uçan Doktor'], 'Molière, 1673\'te sahnelenen son eseri Hastalık Hastası\'nda (Le Malade imaginaire) bizzat Argan rolünü oynarken sahnede kan öksürerek fenalaşmış ve birkaç saat sonra evinde ölmüştür.'),
  ('Karnını iki kat doyurabilmek için Venedik\'te birbirinden habersiz iki ayrı beyefendinin (erkek kılığındaki Beatrice ile sevgilisi Florindo\'nun) hizmetine aynı anda giren açıkgöz Truffaldino\'nun telaşını anlatan Goldoni eseri hangisidir?', 'İki Efendinin Uşağı', ['Yelpaze', 'Kahvehane', 'Dedikoducu Kadınlar'], 'Goldoni\'nin 1745\'te ünlü Arlecchino oyuncusu Antonio Sacchi için yazdığı İki Efendinin Uşağı, özellikle aynı anda iki odaya yemek servisi yapılan sahnesiyle dünya klasiğidir.'),
  ('Habsburg valisi Gessler\'in meydana diktiği şapkaya selam vermeyi reddettiği için öz oğlunun başı üzerindeki elmayı okla vurmaya zorlanan İsviçreli özgürlük kahramanını konu alan son tamamlanmış Schiller dramı hangisidir?', 'Wilhelm Tell', ['Don Carlos', 'Wallenstein', 'Orléans Bakiresi'], 'Schiller\'in 1804 tarihli Wilhelm Tell oyunu, yabancı zorbalığa karşı bir ulusun meşru direniş hakkını yücelten görkemli bir özgürlük destanıdır.'),
  ('Goethe\'nin altmış yıla yayılan bir emekle iki bölüm halinde tamamladığı başyapıtında, tüm bilimleri tükettiği halde yaşama doymayan yaşlı bilginin \'Dur ey an, ne kadar güzelsin!\' diyeceği doygunluk anına karşılık iddiaya girdiği şeytan figürü kimdir?', 'Mephistopheles', ['Wagner', 'Homunculus', 'Valentin'], 'Goethe\'nin Faust yapıtında Tanrı ile Gökte Öndeyiş sahnesinde bahse tutuşan Mephistopheles, sürekli çabalayan insanı (Faust) rehavete düşürüp ruhunu kazanmaya çalışır.'),
  ('1827\'de yayımladığı Cromwell adlı oyununun ünlü önsözünde Klasisizmin üç birlik kuralını yıkarak doğada olduğu gibi sanatta da \'yüce (sublime) ile gülünç/ucube olanın (grotesk)\' yan yana bulunması gerektiğini savunup romantik dramın bildirisini yazan kimdir?', 'Victor Hugo', ['Alphonse de Lamartine', 'Théophile Gautier', 'François-René de Chateaubriand'], 'Victor Hugo\'nun Cromwell Önsözü, trajedi ile komediyi ayıran klasik duvarları yıkmış ve modern romantik dram türünün kuramsal manifestosu olmuştur.'),
  ('Edmond Rostand\'ın 1897\'de geç dönem neoromantik coşkuyla yazdığı manzum oyunda, iri burnu yüzünden güzeller güzeli kuzeni Roxane\'a aşkını açamayıp yakışıklı ama söz yeteneği kıt Christian\'ın adına aşk mektupları yazan silahşor şair kimdir?', 'Cyrano de Bergerac', ['Şövalye Des Grieux', 'Vikont de Valmont', 'D\'Artagnan'], 'Tarihsel bir 17. yüzyıl şairinden esinlenen Cyrano de Bergerac; balkon sahnesi, burun tiradı ve on dört yıl sonra manastır bahçesinde sonbahar yaprakları altında okunan son mektupla tiyatro tarihinin en sevilen kahramanlarındandır.'),
  ('Padovalı zengin Baptista\'nın huysuz ve dik başlı büyük kızı Katharina\'yı evcilleştirmeye talip olan Veronalı Petruchio\'nun fırtınalı düğün ve inatlaşma sürecini işleyen Shakespeare komedyası hangisidir?', 'Hırçın Kız', ['Windsor\'un Şen Kadınları', 'Yanlışlıklar Komedyası', 'Aşkın Çabası Boşuna'], 'Tiyatro içinde tiyatro (sarhoş tenekeci Christopher Sly çerçevesi) ile başlayan Hırçın Kız (The Taming of the Shrew), Katharina ile Petruchio\'nun zekâ dolu çekişmesiyle ünlüdür.'),
  ('Klasisizm akımının trajedi anlayışı ile Romantizm akımının dram anlayışı karşılaştırıldığında hangisi Romantizmin getirdiği yeniliklerden biridir?', 'Ulusal tarih ve Orta Çağ konularına yönelerek soylu-halk ayrımını kaldırması ve sahne diline günlük konuşmanın canlılığını katması', ['Olayları yalnızca yirmi dört saatlik zaman dilimine ve sarayın tek bir kabul salonuna sıkıştırması', 'Yalnızca Yunan ve Latin mitolojisindeki yarı tanrıların akıl-tutku çatışmasını işleyip yerli konuları yasaklaması', 'Bireysel duyguları ve öznelliği bastırarak evrensel, değişmez insan tipini kuralcı bir dille yansıtması'], 'Romantik dram; Klasisizmin Antik Çağ zorunluluğunu, üç birlik kuralını, seçkinci yüksek dilini ve trajedi-komedi ayrımını yıkarak ulusal tarihe, yerel renge ve özgür biçime yönelmiştir.'),
  ('Karısı Martine\'den yediği dayağın öcünü almak isteyen kadının \'kocam çok büyük bir doktordur ama dayak yemeden mesleğini asla itiraf etmez\' iftirası yüzünden oduncu Sganarelle\'in dilsiz numarası yapan Lucinde\'i tedavi etmeye götürüldüğü Molière farsı hangisidir?', 'Zoraki Hekim', ['Scapin\'in Dolapları', 'Hastalık Hastası', 'Zoraki Evlenme'], 'Molière\'in 1666 tarihli Zoraki Hekim (Le Médecin malgré lui) oyunu, Ahmet Vefik Paşa tarafından Türkçeye Zoraki Tabip adıyla uyarlanmış en neşeli komedyalardandır.'),
  ('19. yüzyıl ortasında Romantizmin aşırı coşkusuna tepki olarak Genç Alexandre Dumas\'nın 1852\'de kendi romanından sahneye uyarladığı, veremli kibar fahişe Marguerite Gautier\'nin sevgilisi Armand Duval\'in aile onuru için aşkından vazgeçişini işleyen realist geçiş oyunu hangisidir?', 'Kamelyalı Kadın', ['Arles\'lı Kız', 'Thérèse Raquin', 'Kargalar'], 'Genç Dumas\'nın Kamelyalı Kadın (La Dame aux camélias) dramı, Verdi\'nin La Traviata operasına kaynak olmuş ve çağdaş toplumsal sorunları işleyen gerçekçi \'tezli oyun\' dönemini başlatmıştır.'),
  ('19. yüzyıl başında kitlelerin doldurduğu bulvar tiyatrolarında gelişen; keskin iyi-kötü karşıtlığına, masum kurbanların çektiği acılara, tesadüflere ve fon müziği eşliğinde erdemin sonunda ödüllendirildiği duygusal gerilime dayanan popüler oyun türü hangisidir?', 'Melodram', ['Fars', 'Absürt dram', 'Satir oyunu'], 'Yunanca \'melos\' (müzik) ve \'drama\' sözcüklerinden türeyen ve Pixérécourt ile Fransa\'da kurumsallaşan melodram, müzik eşliğinde keskin siyah-beyaz ahlaki çatışma ve aşırı duygusallık sunan türdür.'),
  ('Shakespeare\'in trajedilerindeki \'trajik zaaf / tutku\' eşleştirmelerinden hangisi eserin ana çatışmasıyla örtüşmez?', 'Kral Lear – Genç yaşta tahtı zorla ele geçirme ve komşu krallıkları istila etme hırsı', ['Macbeth – Kehanetlerle kışkırtılan dizginsiz iktidar ve taç tutkusu', 'Othello – Özgüven sarsıntısı ve kışkırtılmış yıkıcı kıskançlık', 'Hamlet – Eyleme geçmeyi geciktiren aşırı sorgulama ve melankolik kuşku'], 'Kral Lear genç bir fatih değil, seksenini aşmış yorgun bir kraldır; onun trajik yanılgısı tahtı bırakırken dalkavukluğa kanması, kibri ve gerçek sevgiyi ölçememesidir.'),
  ('Rönesans\'tan 19. yüzyıla uzanan süreçte sahne önü çerçevesiyle (proscenium kemeri) seyirci salonunu sahneden keskin biçimde ayıran ve perspektif dekorla yanılsama yaratan salon tipine dünya tiyatrosunda ne ad verilir?', 'İtalyan sahne (Çerçeve / Kutusal sahne)', ['Meydan sahnesi (Arena / Orta oyunu)', 'Uzantılı Elizabeth platform sahnesi', 'Antik dairesel orkestra sahnesi'], '17. yüzyıl İtalya\'sında (ilk kalıcı proscenium kemerli Teatro Farnese, Parma, 1618) olgunlaşan \'İtalyan sahne\', resimsel çerçeve içinde gerçeklik yanılsaması sunan klasik Batı sahne tipidir.'),
  ('Klasik Fransız komedyasında Molière\'in yarattığı kahramanlardan hangisi \'sonradan görme sınıf atlama özentisi\' yerine doğrudan \'aşılmaz cimrilik ve tefecilik saplantısını\' temsil eder?', 'Harpagon', ['Mösyö Jourdain', 'Tartuffe', 'Argan'], 'Mösyö Jourdain kibarlık ve soyluluk özentisini, Tartuffe sahte dindarlığı, Argan hastalık kuruntusunu; Harpagon ise Cimri oyununda para ve tefecilik saplantısını simgeler.'),
  ('Goethe ve Schiller\'in 1790\'ların sonunda Almanya\'nın hangi küçük düklük kentindeki saray tiyatrosunda yürüttükleri ortak çalışma \'Klasisizm\' (Antik Yunan uyumu ile modern hümanizmin birleşimi) dönemine adını vermiştir?', 'Weimar', ['Dresden', 'Münih', 'Heidelberg'], 'Dük Karl August\'un davetiyle Goethe\'nin yerleştiği ve Schiller\'in de katıldığı Weimar kenti, Alman edebiyat ve tiyatro tarihinde \'Weimar Klasisizmi\'nin (Weimarer Klassik) başkentidir.'),
  ('Shakespeare\'in Hamlet oyununda nişanlısı Prens\'in sarsıcı davranışları ve babası Polonius\'un perde arkasında yanlışlıkla öldürülmesi üzerine aklını yitirip çiçekler ve türküler dağıtarak derede boğulan trajik genç kız kimdir?', 'Ophelia', ['Desdemona', 'Cordelia', 'Lavinia'], 'Biberiye, hercai menekşe ve sedef otu dağıtarak delilik türküleri söyleyen Ophelia\'nın söğüt dalı kırılınca sulara gömülüşü, hem tiyatronun hem de dünya resim sanatının (Millais) simge sahnelerindendir.'),
  ('Modern gerçekçi tiyatronun kurucusu kabul edilen ve "Bir Bebek Evi (Nora)" adlı eseriyle tanınan Norveçli oyun yazarı kimdir?', 'Henrik Ibsen', ['August Strindberg', 'Björnstjerne Björnson', 'Knut Hamsun'], 'Henrik Ibsen, bireysel özgürlük ve burjuva ahlakını sorgulayan "Bir Bebek Evi" ile modern gerçekçi tiyatronun öncüsü olmuştur.'),
  ('Henrik Ibsen\'in "Bir Bebek Evi" adlı oyununda evliliğini ve toplumsal rolleri sorgulayarak evini terk eden başkahraman kimdir?', 'Nora Helmer', ['Hedda Gabler', 'Bayan Alving', 'Rebekka West'], 'Oyunun sonunda kapıyı çarpıp çıkarak kadın özgürleşmesinin simgesi haline gelen karakter Nora Helmer\'dir.'),
  ('Henrik Ibsen\'in manzum olarak kaleme aldığı, Norveç halk masallarından beslenen ve hayalperest bir köylü gencin maceralarını anlatan eseri hangisidir?', 'Peer Gynt', ['John Gabriel Borkman', 'Rosmersholm', 'Biz Ölüler Uyanınca'], 'Edvard Grieg\'in ünlü sahne müziğiyle de tanınan "Peer Gynt", Ibsen\'in gerçekçi dönem öncesi yazdığı manzum başyapıtıdır.'),
  ('"Martı", "Vanya Dayı", "Üç Kız Kardeş" ve "Vişne Bahçesi" adlı başyapıtlarıyla modern tiyatroya yön veren Rus yazar kimdir?', 'Anton Çehov', ['Maksim Gorki', 'Nikolay Gogol', 'İvan Turgenyev'], 'Anton Çehov, bu dört büyük oyunuyla psikolojik gerçekçilik ve durum tiyatrosunun zirvesini oluşturmuştur.'),
  ('Anton Çehov\'un oyunlarını büyük bir başarıyla sahneleyen ve Çehov\'un "Martı" figürünü tiyatrosunun amblemi yapan ünlü Rus tiyatro kurumu hangisidir?', 'Moskova Sanat Tiyatrosu', ['Bolşoy İmparatorluk Tiyatrosu', 'Mariinski Kraliyet Tiyatrosu', 'Meyerhold Devrim Tiyatrosu'], 'Konstantin Stanislavski ve Vladimir Nemiroviç-Dançenko\'nun kurduğu Moskova Sanat Tiyatrosu, 1898\'de "Martı" ile büyük başarı kazanmıştır.'),
  ('Çehov\'un "Eğer birinci perdede duvarda bir tüfek asılıysa, sonraki perdelerde mutlaka patlamalıdır." sözü oyun yazarlığında hangi ilkeyi vurgular?', 'Dramatik ekonomi ve kurgudaki her öğenin işlevsel bir zorunluluk taşıması gerektiğini', ['Gerçekçi tiyatroda mutlaka ateşli silahların ve şiddet sahnelerinin bulunması zorunluluğunu', 'Sahne dekorunun olabildiğince kalabalık ve görkemli eşyalarla doldurulması gerektiğini', 'Oyunların her zaman beklenmedik bir cinayet vakasıyla sona ermesi kuralını'], '"Çehov\'un tüfeği" ilkesi, eserde gereksiz hiçbir ayrıntıya yer verilmemesi gerektiğini anlatan temel dramatik kurgu kuralıdır.'),
  ('1925 yılında Nobel Edebiyat Ödülü\'nü kazanan, "Pygmalion" ve "Ermiş Jeanne" gibi eserleriyle tanınan İrlanda asıllı İngiliz oyun yazarı kimdir?', 'George Bernard Shaw', ['Oscar Wilde', 'John Millington Synge', 'Sean O\'Casey'], 'Bernard Shaw, keskin zekası ve toplumsal eleştirileriyle İngilizcede Shakespeare sonrası en etkili oyun yazarlarından biri kabul edilir.'),
  ('Bernard Shaw\'un "Pygmalion" adlı oyununda sesbilim profesörü Henry Higgins\'in konuşmasını düzelterek sosyeteye bir düşes gibi sunmaya çalıştığı çiçekçi kız kimdir?', 'Eliza Doolittle', ['Vivie Warren', 'Candida Morell', 'Barbara Undershaft'], 'Kenar mahalle şivesiyle konuşan çiçekçi kız Eliza Doolittle, Higgins ile Albay Pickering\'in girdiği iddia sonucunda eğitim alır.'),
  ('"Altı Karakter Yazarını Arıyor" adlı eseriyle modern tiyatroda gerçeklik ve yanılsama sınırlarını yıkan Nobel ödüllü İtalyan yazar kimdir?', 'Luigi Pirandello', ['Carlo Goldoni', 'Dario Fo', 'Gabriele D\'Annunzio'], '1934 Nobel Edebiyat Ödülü sahibi Luigi Pirandello, grotesk ve üst-tiyatro (metatiyatro) anlayışının en büyük ustasıdır.'),
  ('"Kanlı Düğün", "Yerma" ve "Bernarda Alba\'nın Evi" adlı köy trajedileriyle dünya tiyatrosunda iz bırakan İspanyol şair ve oyun yazarı kimdir?', 'Federico García Lorca', ['Pedro Calderón de la Barca', 'Lope de Vega', 'Ramón del Valle-Inclán'], '1936\'da İspanya İç Savaşı başında kurşuna dizilerek öldürülen Lorca, şiirsel ve simgesel halk trajedilerinin büyük ustasıdır.'),
  ('Lorca\'nın "Bernarda Alba\'nın Evi" adlı oyununda kocasının ölümünden sonra beş kızına sekiz yıllık ağır bir yas ve ev hapsi dayatan otoriter anne neyi simgeler?', 'Baskıcı geleneksel toplum düzenini, bağnaz ahlak anlayışını ve diktatörce otoriteyi', ['Çocuklarını savaş tehlikesinden korumaya çalışan özverili ve şefkatli taşra anneliğini', 'Endülüs köylerinde kadınların ekonomik bağımsızlık kazanmak için kurdukları dayanışmayı', 'Modern tarım tekniklerine direnen feodal toprak ağalarının doğa sevgisini'], 'Sahnede hiç erkek karakterin görünmediği oyunda Bernarda Alba, bireysel tutkuları ezen kör otorite ve baskının simgesidir.'),
  ('Doğalcı (natüralist) tiyatronun yanı sıra dışavurumcu tiyatronun da öncüsü sayılan ve "Matmazel Julie" adlı oyunuyla tanınan İsveçli yazar kimdir?', 'August Strindberg', ['Henrik Ibsen', 'Pär Lagerkvist', 'Hjalmar Söderberg'], 'İsveçli yazar August Strindberg, hem natüralist "Matmazel Julie" hem de dışavurumcu "Bir Düş Oyunu" ile modern tiyatroyu derinden etkilemiştir.'),
  ('19. yüzyıl sonunda Paris\'te "Théâtre Libre"i (Özgür Tiyatro) kurarak doğalcı (natüralist) sahnelemenin ve "dördüncü duvar" anlayışının öncüsü olan yönetmen kimdir?', 'André Antoine', ['Jacques Copeau', 'Antonin Artaud', 'Jean Vilar'], 'André Antoine, 1887\'de kurduğu Théâtre Libre ile sahnede gerçek yaşam dilimleri sunan natüralist yönetmenliğin temelini atmıştır.'),
  ('Oscar Wilde\'ın Viktorya dönemi İngiliz sosyetesinin ikiyüzlülüğünü keskin nüktelerle eleştirdiği en ünlü komedyası hangisidir?', 'Ciddi Olmanın Önemi', ['Lady Windermere\'in Yelpazesi', 'Reading Zindanı Baladı', 'Dorian Gray\'in Portresi'], 'Oscar Wilde\'ın 1895 tarihli "The Importance of Being Earnest" (Ciddi Olmanın Önemi) adlı eseri, İngiliz töre komedyasının en parlak örneklerinden biridir.'),
  ('Fransız yazar Edmond Rostand\'ın 1897\'de kaleme aldığı, iri burnu yüzünden sevdiği Roxane\'a aşkını doğrudan açamayan şair ruhlu silahşoru anlatan ünlü manzum oyunu hangisidir?', 'Cyrano de Bergerac', ['Hernani', 'Ruy Blas', 'Lorenzaccio'], 'Gerçekçi tiyatronun egemen olduğu bir dönemde yeni-romantik bir zafer kazanan "Cyrano de Bergerac", dünya tiyatrosunun en sevilen oyunlarındandır.'),
  ('Modern Amerikan tiyatrosunun kurucusu kabul edilen, 1936 Nobel Edebiyat Ödülü sahibi ve "Günden Geceye" (Uzun Günün Geceye Yolculuğu) adlı başyapıtın yazarı kimdir?', 'Eugene O\'Neill', ['Thornton Wilder', 'Clifford Odets', 'William Inge'], 'Eugene O\'Neill, dört kez Pulitzer ve bir kez Nobel kazanarak Amerikan tiyatrosunu hafif eğlence sahnesinden derinlikli trajedi düzeyine çıkarmıştır.'),
  ('20. yüzyıl tiyatrosunda "Epik Tiyatro" (Diyalektik Tiyatro) kuramını geliştiren ve "Üç Kuruşluk Opera" ile dünya çapında ün kazanan Alman yazar kimdir?', 'Bertolt Brecht', ['Friedrich Dürrenmatt', 'Max Frisch', 'Peter Weiss'], 'Bertolt Brecht, Aristotelesçi dramatik tiyatroya karşı geliştirdiği epik-diyalektik tiyatro kuramıyla modern sahnenin en etkili isimlerinden biri olmuştur.'),
  ('Brecht\'in Otuz Yıl Savaşları sırasında seyyar arabasıyla orduların peşinden giderek savaştan geçimini sağlamaya çalışırken üç çocuğunu da yitiren kadını anlattığı başyapıtı hangisidir?', 'Cesaret Ana ve Çocukları', ['Kafkas Tebeşir Dairesi', 'Sezuan\'ın İyi İnsanı', 'Galileo\'nun Yaşamı'], 'Anna Fierling (Cesaret Ana), savaştan kâr elde etmeye çalışırken evlatlarını savaşa kurban veren trajik-eleştirel bir figürdür.'),
  ('Absürt (Uyumsuz) tiyatronun en önemli başyapıtı sayılan "Godot\'yu Beklerken" adlı eserin 1969 Nobel Edebiyat Ödülü sahibi İrlandalı yazarı kimdir?', 'Samuel Beckett', ['Eugène Ionesco', 'Harold Pinter', 'Jean Genet'], 'İrlanda doğumlu olup eserlerinin çoğunu Fransızca yazan Samuel Beckett, "Godot\'yu Beklerken" ile 20. yüzyıl tiyatrosunun akışını değiştirmiştir.'),
  ('Samuel Beckett\'in "Godot\'yu Beklerken" adlı oyununda ıssız bir yol kenarındaki kuru ağacın altında hiç gelmeyen Godot\'yu bekleyen iki serseri karakter kimlerdir?', 'Vladimir ve Estragon', ['Hamm ve Clov', 'Pozzo ve Lucky', 'Winnie ve Willie'], 'Birbirlerine "Didi" ve "Gogo" diye seslenen Vladimir ve Estragon, zamanı öldürmek için anlamsız oyunlar oynayarak Godot\'yu beklerler.'),
  ('"Kel Şarkıcı", "Ders", "Sandalyeler" ve "Gergedanlar" gibi oyunlarıyla absürt tiyatronun en önemli kurucularından biri olan Rumen asıllı Fransız yazar kimdir?', 'Eugène Ionesco', ['Arthur Adamov', 'Fernando Arrabal', 'Jean Tardieu'], 'Eugène Ionesco, dilin iletişimsizliğini ve konformizmin tehlikesini grotesk bir mizahla sahneye taşımıştır.'),
  ('"Satıcının Ölümü", "Cadı Kazanı" ve "Köprüden Görünüş" adlı eserleriyle 20. yüzyıl Amerikan toplumsal gerçekçi trajedisine damga vuran yazar kimdir?', 'Arthur Miller', ['Tennessee Williams', 'Edward Albee', 'Sam Shepard'], 'Arthur Miller, bireyin toplumsal baskılar ve Amerikan Rüyası\'nın yıkıcı yanılsamaları karşısındaki ahlaki sınavlarını işlemiştir.'),
  ('Arthur Miller\'ın "Satıcının Ölümü" adlı başyapıtında yıllarca çalıştığı şirketten kovulan, Amerikan Rüyası\'na körü körüne inanmış trajik gezgin satıcı karakter kimdir?', 'Willy Loman', ['John Proctor', 'Eddie Carbone', 'Joe Keller'], 'Willy Loman, "sevilmek ve başarılı görünmek" üzerine kurulu sahte Amerikan başarı mitinin kurbanı olan modern trajedi kahramanıdır.'),
  ('"Sırça Kümes", "İhtiras Tramvayı" ve "Kızgın Damdaki Kedi" adlı oyunlarıyla Güney Amerika atmosferini şiirsel gerçekçilikle sahneye taşıyan yazar kimdir?', 'Tennessee Williams', ['William Faulkner', 'Truman Capote', 'Lillian Hellman'], 'Tennessee Williams, kaba ve maddeci gerçeklik karşısında ezilen kırılgan ruhların dramını lirik ve simgesel bir dille yazmıştır.'),
  ('"Kim Korkar Hain Kurttan?" (Who\'s Afraid of Virginia Woolf?) adlı sarsıcı oyunuyla Amerikan aile yapısının ve evlilik kurumunun ardındaki yanılsamaları deşen yazar kimdir?', 'Edward Albee', ['Harold Pinter', 'David Mamet', 'Neil Simon'], 'Hem gerçekçi psikolojik çatışmayı hem de "Hayvanat Bahçesi Öyküsü" ile Amerikan absürt tiyatrosunu ustalıkla birleştiren yazar Edward Albee\'dir.'),
  ('2005 Nobel Edebiyat Ödülü sahibi olan, diyaloglarındaki tehditkar sessizlikler nedeniyle edebiyat sözlüğüne "Pinteresk" kavramını kazandıran İngiliz yazar kimdir?', 'Harold Pinter', ['Tom Stoppard', 'John Osborne', 'Edward Bond'], '"Doğum Günü Partisi", "Kapıcı" ve "Aldatma" gibi oyunların yazarı Harold Pinter, "tehdit komedyaları" ve suskunluk kullanımıyla ünlüdür.'),
  ('Fransız varoluşçu filozof ve yazar Jean-Paul Sartre\'ın "Cehennem başkalarıdır!" (L\'enfer, c\'est les autres) özdeyişiyle ünlenen ve kilitli bir odadaki üç ölüyü anlatan oyunu hangisidir?', 'Gizli Oturum', ['Sinekler', 'Kirli Eller', 'Mezarsız Ölüler'], 'Sartre\'ın "Gizli Oturum" (Huis Clos) adlı eserinde Garcin, Inès ve Estelle birbirlerinin bakışları altında sonsuz bir vicdan ve kimlik işkencesi yaşarlar.'),
  ('İsviçreli oyun yazarı Friedrich Dürrenmatt\'ın iflas etmiş Güllen kasabasına dönen milyarder Claire Zachanassian\'ın eski sevgilisinin öldürülmesi karşılığında kasabaya servet vaat etmesini anlatan trajikomedyası hangisidir?', 'Yaşlı Hanımın Ziyareti', ['Fizikçiler', 'Büyük Romulus', 'Melek Babil\'e İniyor'], '"Yaşlı Hanımın Ziyareti", paranın satın alma gücü karşısında sıradan ve "namuslu" kasaba halkının ahlaki değerlerini adım adım nasıl sattığını grotesk biçimde gösterir.'),
  ('1997 Nobel Edebiyat Ödülü\'nü kazanan, İtalyan halk güldürüsü (Commedia dell\'arte) geleneğini politik taşlamayla birleştiren "Bir Anarşistin Kaza Sonucu Ölümü" adlı eserin yazarı kimdir?', 'Dario Fo', ['Eduardo De Filippo', 'Ugo Betti', 'Carlo Gozzi'], 'Dario Fo (eşi Franca Rame ile birlikte), Orta Çağ jonglör geleneğini çağdaş politik farsla birleştirerek otoriteyi ve yolsuzlukları hicvetmiştir.'),
  ('Batılı anlamda Türk edebiyatında yazılan ilk tiyatro eseri olan "Şair Evlenmesi" hangi sanatçıya aittir?', 'İbrahim Şinasi', ['Namık Kemal', 'Ahmet Vefik Paşa', 'Recaizade Mahmut Ekrem'], '"Şair Evlenmesi", İbrahim Şinasi tarafından 1860 yılında Tercüman-ı Ahval gazetesinde tefrika edilen ilk yerli tiyatro eseridir.'),
  ('İbrahim Şinasi\'nin kaleme aldığı "Şair Evlenmesi" adlı tek perdelik tiyatro eserinin türü nedir?', 'Töre komedyası', ['Tarihsel trajedi', 'Felsefi dram', 'Müzikli vodvil'], '"Şair Evlenmesi", görücü usulüyle evlenmenin sakıncalarını mizahi bir dille eleştiren tek perdelik bir töre komedyasıdır.'),
  ('Türk edebiyatında sahnelenen ilk tiyatro eseri olan "Vatan yahut Silistre" kimin tarafından yazılmıştır?', 'Namık Kemal', ['İbrahim Şinasi', 'Abdülhak Hamit Tarhan', 'Ahmet Mithat Efendi'], '"Vatan yahut Silistre", Namık Kemal tarafından yazılmış ve 1 Nisan 1873\'te Gedikpaşa Tiyatrosu\'nda sahnelenmiştir.'),
  ('"Vatan yahut Silistre" oyununun 1873\'te sahnelenmesinin ardından halkın coşkulu gösterileri üzerine Namık Kemal nereye sürgün edilmiştir?', 'Magosa', ['Rodos', 'Midilli', 'Fizan'], 'Oyunun Gedikpaşa Tiyatrosu\'nda yarattığı vatanperverlik heyecanı üzerine İbret gazetesi kapatılmış ve Namık Kemal Kıbrıs\'taki Magosa Kalesi\'ne sürgün edilmiştir.'),
  ('Namık Kemal\'in tiyatro eserlerinde benimsediği edebi akım aşağıdakilerden hangisidir?', 'Romantizm', ['Klasisizm', 'Realizm', 'Natüralizm'], 'Namık Kemal, Victor Hugo\'nun "Cromwell" önsözünden etkilenmiş; oyunlarında iyilerle kötülerin keskin çatışması, coşkulu vatan/aşk tiratları ve dram türüyle romantizmi benimsemiştir.'),
  ('Bursa valiliği sırasında tiyatro binası kurduran ve Moliere\'den yaptığı uyarlamalarla (adaptasyon) Türk tiyatrosuna büyük katkı sağlayan devlet ve edebiyat adamı kimdir?', 'Ahmet Vefik Paşa', ['Direktör Ali Bey', 'Şemsettin Sami', 'Muallim Naci'], 'Ahmet Vefik Paşa, Moliere\'in pek çok komedyasını Osmanlı toplum yaşamına uyarlamış ve Bursa\'da tiyatro kurarak memurların tiyatroya gitmesini teşvik etmiştir.'),
  ('Osmanlı toplumundaki kurumların yozlaşmasını, batıl inançları ve esnaf hayatını renkli bir sahne diliyle komedya türünde işleyen, Milli Edebiyat\'tan Cumhuriyet\'e uzanan usta oyun yazarı kimdir?', 'Musahipzade Celal', ['İbnürrefik Ahmet Nuri Sekizinci', 'Aka Gündüz', 'Reşat Nuri Güntekin'], 'Musahipzade Celal, konularını çoğunlukla Osmanlı tarihinden ve İstanbul\'un geleneksel mahalle/lonca yaşamından alan töre ve hiciv komedyalarıyla tanınır.'),
  ('Darülbedayi\'de 1920 yılında Hüseyin Rahmi Gürpınar\'ın "Yamalar" adlı oyununda "Emel" rolüyle sahneye çıkarak Türk tiyatrosunun ilk Müslüman Türk kadın oyuncusu olan sanatçı kimdir?', 'Afife Jale', ['Bedia Muvahhit', 'Cahide Sonku', 'Yıldız Kenter'], 'Afife Jale, Kadıköy Apollon Tiyatrosu\'nda sahnelenen "Yamalar" oyununda "Jale" takma adıyla sahneye çıkarak Müslüman Türk kadınlarının sahne yasağını delen öncü isim olmuştur.'),
  ('Çağdaş Türk tiyatrosunun kurumsallaşmasında yönetmen, oyuncu, çevirmen ve idareci olarak en büyük rolü üstlenen, Şehir Tiyatroları ve Devlet Tiyatroları\'nın gelişimine öncülük eden sanatçı kimdir?', 'Muhsin Ertuğrul', ['Cüneyt Gökçer', 'İsmail Dümbüllü', 'Haldun Dormen'], 'Muhsin Ertuğrul, Batılı sahneleme tekniklerini, disiplinli prova düzenini, çocuk tiyatrolarını ve çağdaş repertuvar anlayışını Türkiye\'ye yerleştiren modern Türk tiyatrosunun kurucu ismidir.'),
  ('Türk edebiyatında ilk epik tiyatro örneği kabul edilen "Keşanlı Ali Destanı" adlı eserin yazarı kimdir?', 'Haldun Taner', ['Turgut Özakman', 'Cevat Fehmi Başkut', 'Güngör Dilmen'], 'Haldun Taner\'in yazdığı ve müziklerini Yalçın Tura\'nın bestelediği "Keşanlı Ali Destanı" (1964), Türk tiyatrosunda epik tiyatronun ilk ve en başarılı örneği sayılır.'),
  ('Yurt dışında sahnelenen ilk Türk tiyatro eseri olma özelliğini taşıyan "Paydos" adlı oyunun yazarı aşağıdakilerden hangisidir?', 'Cevat Fehmi Başkut', ['Turgut Özakman', 'Orhan Asena', 'Recep Bilginer'], 'Gazeteci ve oyun yazarı Cevat Fehmi Başkut\'un 1948\'de yazdığı "Paydos", Atina\'da sahnelenerek yurt dışında oynanan ilk Türk piyesi olmuştur.'),
  ('Milli Edebiyat Dönemi\'nde "Hisse-i Şayia" ve "Ceza Kanunu" gibi başarılı uyarlama komedyalarıyla tanınan oyun yazarı kimdir?', 'İbnürrefik Ahmet Nuri Sekizinci', ['Musahipzade Celal', 'Halit Fahri Ozansoy', 'Aka Gündüz'], 'İbnürrefik Ahmet Nuri Sekizinci, Fransız vodvil ve bulvar komedyalarını Türk aile yapısına ustalıkla uyarlamış; Darülbedayi\'nin kuruluş ve gelişim sürecinde önemli rol oynamıştır.'),
  ('Şinasi\'nin "Şair Evlenmesi" eserinde noktalama işaretlerini kullanması Türk edebiyatı tarihi açısından hangi yeniliğin başlangıcı kabul edilir?', 'Türk edebiyatında noktalama işaretlerinin ilk kez bir edebi metinde kullanılmasının', ['Arap alfabesinden Latin alfabesine resmi geçişin tamamlanmasının', 'Hece ölçüsünün tiyatro diyaloglarında zorunlu hale getirilmesinin', 'Yabancı kelimelerin sözlüklerden tamamen çıkarılmasının'], 'Şinasi, "Şair Evlenmesi"nde yay ayraç (parantez) ve kısa çizgi gibi ilk noktalama işaretlerini kullanarak metnin sahnede nasıl okunacağını ve oynanacağını göstermiştir.'),
  ('Ahmet Mithat Efendi\'nin 1884\'te yazdığı "Çerkez Özdenleri" adlı oyunun sahnelenmesinin ardından Osmanlı yönetimi hangi tiyatro binasını yıktırmıştır?', 'Gedikpaşa Tiyatrosu', ['Naum Tiyatrosu', 'Tepebaşı Tiyatrosu', 'Ferah Tiyatrosu'], 'Ahmet Mithat Efendi\'nin "Çerkez Özdenleri" oyunundaki bağımsızlık ve hürriyet çağrışımlarından rahatsız olan saray yönetimi, Güllü Agop\'un çalıştırdığı Gedikpaşa Tiyatrosu\'nu 1884\'te yıktırmıştır.'),
  ('Geleneksel Türk tiyatrosunda ustadan çırağa devredilen "kavuk", tuluat ustası İsmail Dümbüllü\'den sonra ilk olarak hangi tiyatro sanatçısına geçmiştir?', 'Münir Özkul', ['Ferhan Şensoy', 'Rasim Öztekin', 'Zeki Alasya'], 'Kel Hasan Efendi\'den İsmail Dümbüllü\'ye geçen geleneksel tiyatro simgesi kavuk, 1968 yılında Dümbüllü tarafından Münir Özkul\'a devredilmiştir.'),
  ('"Şu Çılgın Türkler" romanının yanı sıra "Ah Şu Gençler", "Fehim Paşa Konağı" ve "Töre" gibi sevilen tiyatro eserlerini kaleme alan yazar kimdir?', 'Turgut Özakman', ['Güngör Dilmen', 'Turan Oflazoğlu', 'Orhan Asena'], 'Dramaturg, araştırmacı ve yazar Turgut Özakman, hem geleneksel tiyatro öğelerini kullanan tarihsel-toplumsal oyunları hem de kuşak çatışmasını işleyen modern piyesleriyle tanınır.'),
  ('Antik Yunan ve Anadolu mitolojisinden beslenen şiirsel oyunlarıyla tanınan, "Midas\'ın Kulakları" adlı eserin yazarı olan tiyatrocumuz kimdir?', 'Güngör Dilmen', ['Orhan Asena', 'Turan Oflazoğlu', 'Refik Erduran'], 'Güngör Dilmen (Kalyoncu), özellikle Frigya Kralı Midas\'ı konu alan üçlemesiyle Türk tiyatrosunda mitolojik ve şiirsel tiyatronun en güçlü temsilcilerinden biri olmuştur.'),
  ('Türk tiyatrosunun "Shakespeare\'i" olarak nitelendirilen, Mezopotamya ve Osmanlı tarihinden aldığı konularla iktidar-insan çatışmasını işleyen ve "Tanrılar ve İnsanlar" oyunuyla tanınan yazar kimdir?', 'Orhan Asena', ['Turan Oflazoğlu', 'Cevat Fehmi Başkut', 'Recep Bilginer'], 'Şair ve çocuk hastalıkları uzmanı da olan Orhan Asena, özellikle "Tanrılar ve İnsanlar (Gılgamış)", "Hürrem Sultan" ve "Atçalı Kel Mehmet" gibi tarihsel-trajik oyunlarıyla Türk tiyatrosunun zirve isimlerindendir.'),
  ('Shakespeare, Kafka ve Nietzsche\'den yaptığı çevirilerin yanı sıra Osmanlı tarihindeki padişahların ruhsal çatışmalarını trajedi boyutunda işleyen; "IV. Murat", "Deli İbrahim" ve "Kösem Sultan" oyunlarının yazarı kimdir?', 'Turan Oflazoğlu', ['Güngör Dilmen', 'Turgut Özakman', 'Necati Cumalı'], 'A. Turan Oflazoğlu, özellikle Osmanlı sarayındaki iktidar trajedisini yüksek bir şiirsel Türkçe ve klasik Batı trajedisi kurgusuyla birleştiren usta tiyatro yazarımızdır.'),
  ('Cumhuriyet Dönemi\'nde 1949 yılında çıkarılan özel bir yasayla Ankara\'da kurulan ve ilk genel müdürlüğünü Muhsin Ertuğrul\'un üstlendiği resmi tiyatro kurumu hangisidir?', 'Devlet Tiyatroları', ['Darülbedayi-i Osmani', 'Gedikpaşa Tiyatrosu', 'Mızıka-i Hümayun'], '1940\'ta Devlet Konservatuvarı Tatbikat Sahnesi olarak başlayan çalışmalar, 1949\'da çıkarılan 5441 sayılı yasayla Devlet Tiyatro ve Operası (Devlet Tiyatroları) kimliğine kavuşmuştur.'),
  ('Tanzimat\'tan Cumhuriyet\'e Türk tiyatrosunun gelişim çizgisi düşünüldüğünde "telif eser" kavramı aşağıdakilerden hangisini ifade eder?', 'Yabancı bir dilden çevrilmeyen veya uyarlanmayan, doğrudan yerli yazar tarafından özgün olarak kaleme alınan eseri', ['Yabancı bir yazarın oyunundaki kişi ve yer adlarının Türk kültürüne göre değiştirilmesiyle oluşturulan eseri', 'Herhangi bir yazılı metne bağlı kalınmadan sahnede oyuncuların o anki doğaçlamasıyla üretilen gösteriyi', 'Yalnızca saray erkanı önünde müzik eşliğinde sergilenmek üzere bestelenen sözsüz bale yapıtını'], 'Telif oyun yazarın doğrudan kendi yaratısı olan özgün eseri; tercüme (çeviri) aslına sadık aktarımı; adaptasyon ise yerlileştirerek uyarlamayı karşılar.'),
  ('Tiyatro terimi olarak bir oyuncunun sahnede karşısındaki kişiye veya seyirciye yönelik yaptığı uzun ve coşkulu konuşmaya ne ad verilir?', 'Tirat', ['Suflör', 'Pandomim', 'Kulis'], 'Özellikle Namık Kemal, Orhan Asena ve Turan Oflazoğlu gibi romantik ve trajik-tarihsel oyun yazarlarının eserlerinde karakterlerin uzun ve etkili konuşmalarına "tirat" denir.'),
  ('Tiyatro sahnesinde oyuncuların unuttuğu sözleri seyirciye duyurmadan fısıltıyla hatırlatan görevliye ne ad verilir?', 'Suflör', ['Dramaturg', 'Rejisör', 'Koreograf'], 'Sahne arkasından ya da özel bölmesinden metni takip ederek oyunculara repliklerini fısıldayan yardımcı görevliye "suflör" denir.'),
  ('Klasik trajedi ve komedyalarda eserin tek bir ana olay etrafında, en fazla yirmi dört saat içinde ve aynı mekanda geçmesini öngören kurala ne ad verilir?', 'Üç birlik kuralı', ['Yabancılaştırma ilkesi', 'Açık biçim tekniği', 'Doğaçlama düzeni'], 'Klasisizm akımının temel ilkelerinden olan "üç birlik kuralı" (zaman, mekan, olay birliği), Tanzimat\'ta romantik dramın (Namık Kemal, Abdülhak Hamit) etkisiyle kırılmıştır.'),
  ('Haldun Dormen tarafından 1955\'te kurulan ve "Sokak Kızı İrma", "Lüküs Hayat" gibi müzikallerle ve bulvar komedyalarıyla özel tiyatro geleneğine öncülük eden topluluk hangisidir?', 'Dormen Tiyatrosu', ['Gülriz Sururi - Engin Cezzar Topluluğu', 'Dostlar Tiyatrosu', 'Ortaoyuncular'], 'Türk tiyatrosunda Batılı anlamda bulvar komedyası ve müzikal türünün ustası olan Haldun Dormen, Cep Tiyatrosu ve ardından Dormen Tiyatrosu ile pek çok usta oyuncunun yetişmesini sağlamıştır.'),
  ('Cumhuriyet Dönemi tiyatrosunda "köy tiyatrosu" olarak adlandırılan yönelimin oyunlarında (Cahit Atay, Hidayet Sayın, Necati Cumalı vb.) en çok işlenen konular arasında aşağıdakilerden hangisi yer alır?', 'Toprak ve su kavgaları, ağalık baskısı, başlık parası, kan davası ve kadının kırsaldaki ezilmişliği', ['Borsa spekülasyonları yapan holding yöneticilerinin uluslararası finans krizlerindeki kayıpları', 'Osmanlı donanmasındaki kalyon kaptanlarının Venediklilerle yaptığı açık deniz muharebeleri', 'Uzay istasyonlarında görev yapan bilim insanlarının yapay zeka robotlarıyla yaşadığı etik tartışmalar'], '1950 ve 1960\'lı yıllarda köy edebiyatına paralel olarak gelişen köy tiyatrolarında kırsal kesimin gerçekçi sorunları (ağalık, töre, eğitimsizlik, su ve toprak mülkiyeti) sahneye taşınmıştır.'),
  ('Musahipzade Celal\'in eski Osmanlı yönetimindeki liyakatsizliği, israfı ve sadrazamlık makamındaki entrikaları eleştirdiği ünlü tarihsel komedyalarından biri hangisidir?', 'Bir Kavuk Devrildi', ['Keşanlı Ali Destanı', 'Cengiz Han\'ın Bisikleti', 'Buzlar Çözülmeden'], '"Bir Kavuk Devrildi", Musahipzade Celal\'in Osmanlı devlet çarkındaki yozlaşmayı kavuk metaforu üzerinden hicvettiği önemli komedyalarından biridir.'),
  ('Güngör Dilmen\'in Dede Korkut Hikayeleri\'nden esinlenerek Azrail\'e meydan okuyan yiğidin ve onun yerine canını vermeyi kabul eden eşinin öyküsünü sahneye uyarladığı eseri hangisidir?', 'Deli Dumrul', ['Midas\'ın Kulakları', 'Canlı Maymun Lokantası', 'Bağdat Hatun'], 'Güngör Dilmen, Dede Korkut boylarından "Duha Koca Oğlu Deli Dumrul" anlatısını geleneksel ve şiirsel öğelerle "Deli Dumrul" adıyla tiyatroya kazandırmıştır.'),
  ('Turan Oflazoğlu\'nun Osmanlı padişahı Sultan İbrahim\'in kafes hayatından tahta çıktıktan sonra yaşadığı derin korkuları, ruhsal dengesizlikleri ve iktidar çıkmazını anlattığı trajedisi hangisidir?', 'Deli İbrahim', ['Genç Osman', 'Yavuz Selim', 'Cem Sultan'], '1967\'de sahnelenen ve Türk Dil Kurumu Tiyatro Ödülü\'nü kazanan "Deli İbrahim", Oflazoğlu\'nun psikolojik derinliği ve şiirsel dili en güçlü trajedilerinden biridir.'),
];
